   "Formal": [
    {"id": "peace-in-home", "s": "Warm wishes to you and your loved ones on Eid; may the day bring peace and happiness to your home.", "m": "May your prayers be accepted, and may the calm of this day stay with you well beyond it.", "l": "I hope you are able to celebrate in good company and at an unhurried pace, and that the coming months bring you good health and steady contentment."},
    {"id": "harmony-community", "s": "My best wishes to you on Eid, a festival that brings neighbours, friends and colleagues together like few other occasions do.", "m": "The tradition of sharing sewaiyan across homes and communities is a lovely reminder of how much goodwill can achieve.", "l": "May this Eid strengthen those bonds of friendship and understanding, and may the year ahead bring you and your loved ones peace and good health."},
    {"id": "gratitude-season", "s": "Eid is a time to pause and be thankful, and I wish you a day of gratitude and quiet joy.", "m": "May Allah bless you with good health, peace of mind and the company of people who matter to you.", "l": "I hope the festival leaves you rested and grateful, and that the months ahead are kind to you and your home."},
    {"id": "compassion-carry-forward", "s": "Eid celebrates generosity and compassion, and I send you my warm wishes on this joyful day.", "m": "May the kindness that marks this day continue in the weeks that follow.", "l": "I hope the occasion brings you as much joy in giving as in receiving, and that its spirit stays with us through the year, in our work and in our communities."},
    {"id": "wishes-from-us", "s": "On behalf of all of us, warm Eid wishes to you and everyone at home.", "m": "We hope you have a joyful celebration and a well-deserved day of rest with the people dearest to you.", "l": "It has been a pleasure working with you, and we look forward to continuing our association. May Allah grant you good health and peace, and may the coming months bring you fulfilling work."}
   ]
