    {"id": "good-company", "s": "आपके जन्मदिन पर आपके आस-पास ऐसे लोग हों जिनके साथ आप पूरी तरह सहज महसूस करें।", "m": "जो याद रखें कि आपको चाय कैसी पसंद है, आपके पुराने किस्सों पर फिर से हँसें, और बिना किसी वजह के फ़ोन कर लें।", "l": "अच्छे लोगों का साथ ज़िंदगी की असली दौलत है। इस साल ये साथ और गहरा हो, और साथ बैठने का वक़्त भी मिले।"},
    {"id": "small-joys", "s": "आपका जन्मदिन बड़ी उम्मीदों से नहीं, छोटी-छोटी अच्छी चीज़ों से भरा हो।", "m": "आराम वाली सुबह, आपका पसंदीदा खाना, किसी पुराने दोस्त का अचानक आया मैसेज, और दोपहर की बेफ़िक्र झपकी।", "l": "आने वाले साल में ऐसे आम दिन ख़ूब आएँ, जो उस वक़्त ख़ास न लगें, पर बाद में वही सबसे ज़्यादा याद आएँ।"},
    {"id": "gentle-with-yourself", "s": "इस जन्मदिन पर थोड़ी वो नरमी अपने लिए भी रखिए, जो सबके लिए आपके दिल में रहती है।", "m": "अच्छे साल का हक़दार होने के लिए सब कुछ सुलझा हुआ होना ज़रूरी नहीं।", "l": "थकान हो तो आराम कीजिए, ज़रूरत हो तो ‘ना’ कहिए, और धीमी ही सही, अपनी तरक़्क़ी पर ख़ुद को शाबाशी दीजिए। ये साल आपके लिए सुकून भरा हो।"},
    {"id": "grateful-look-back", "s": "एक और जन्मदिन, यानी ज़रा रुककर ये देखने का मौक़ा कि अब तक का सफ़र कितना आगे तक आया है।", "m": "पिछले साल कुछ मुश्किल दिन भी रहे होंगे, पर वो निकल गए, और जाते-जाते कुछ सबक़ भी दे गए।", "l": "आज थोड़ा इस पर फ़ख़्र कीजिए, और उन लोगों को याद कीजिए जो हर मोड़ पर साथ खड़े रहे। आपका सफ़र आगे भी यूँ ही धीरे-धीरे, मज़बूती से चलता रहे।"},
    {"id": "something-new", "s": "इस जन्मदिन से शुरू होने वाले साल में आपको कुछ ऐसा नया मिले जो मन में फिर से जिज्ञासा जगा दे।", "m": "कोई नई जगह, कोई नया हुनर, सोच बदल देने वाली कोई किताब, या बस इतवार बिताने का कोई नया तरीक़ा।", "l": "जन्मदिन याद दिलाते हैं कि सीखने की कोई उम्र नहीं होती। आने वाला साल आपको अच्छे मायनों में चौंकाता रहे।"}
